<script lang="ts">
	import Button from '$components/Button.svelte';
	import { PAGE_IDS } from '$lib/types';
	import { MinDiskSizeBytes } from '$lib/constants';
	import { diskSelectionData, pageValid } from '$lib/state.svelte';
	import { t } from '$lib/i18n';

	// @ts-expect-error — generated by Wails
	import { RebootAndClose } from '@wails/go/gui/App.js';

	let { currentPage }: { currentPage: number } = $props();

	const isLastPage = $derived(currentPage === PAGE_IDS.FINISH);
	const isWelcomePage = $derived(currentPage === PAGE_IDS.WELCOME);
	const isInstallationPage = $derived(currentPage === PAGE_IDS.INSTALLATION);
	const showBack = $derived(currentPage > PAGE_IDS.WELCOME && !isLastPage && !isInstallationPage);
	const showNext = $derived(!isLastPage && !isInstallationPage);
	const diskSizeOk = $derived.by(() => {
		if (!diskSelectionData.disk) return false;
		const size = parseInt(diskSelectionData.disk.size, 10);
		return !isNaN(size) && size >= MinDiskSizeBytes;
	});
	const nextDisabled = $derived(currentPage === PAGE_IDS.CONFIRMATION ? !diskSizeOk : !pageValid.value);

	async function handleReboot(): Promise<void> {
		try {
			await RebootAndClose();
		} catch (err) {
			console.error('[AppFooter] Reboot failed:', err);
		}
	}

	const buttonHandler = $derived(isLastPage ? handleReboot : () => {
		document.dispatchEvent(new CustomEvent('go-next', { cancelable: true }));
	});
</script>

<footer class="footer">
	<div class="footer-left">
		{#if showBack}
			<button
				type="button"
				class="nav-btn nav-btn--back"
				disabled={false}
				aria-label={t('nav.back')}
				onclick={() => document.dispatchEvent(new CustomEvent('go-back', { cancelable: true }))}
			>
				<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
					<path d="M15 18l-6-6 6-6"/>
				</svg>
			</button>
		{/if}
	</div>
	<div class="footer-right">
		{#if showNext}
			<button
				type="button"
				class={['nav-btn', { 'nav-btn--disabled': nextDisabled }]}
				disabled={nextDisabled}
				aria-label={t('nav.next')}
				onclick={buttonHandler}
			>
				<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
					<path d="M9 18l6-6-6-6"/>
				</svg>
			</button>
		{:else if isLastPage}
			<Button variant="secondary" onClick={buttonHandler}>{t('page.finish.reboot')}</Button>
		{/if}
	</div>
</footer>

<style>
	.footer {
		display: flex;
		align-items: center;
		justify-content: space-between;
		min-height: var(--footer-height);
		background-color: var(--color-bg-light);
	}

	.footer-left {
		display: flex;
		align-items: center;
		gap: 8px;
		flex: 1;
		justify-content: flex-start;
	}

	.footer-right {
		display: flex;
		align-items: center;
		gap: 8px;
		flex: 1;
		justify-content: flex-end;
	}

	.nav-btn {
		background: transparent;
		border: none;
		border-radius: 50%;
		width: 48px;
		height: 48px;
		display: flex;
		align-items: center;
		justify-content: center;
		color: var(--color-text);
		cursor: pointer;
		transition: background-color 0.15s ease, color 0.15s ease;
		outline: none;
	}

	.nav-btn:hover:not(:disabled) {
		background-color: var(--color-bg-hover);
	}

	.nav-btn:focus-visible {
		box-shadow: 0 0 0 2px var(--color-focus);
	}

	.nav-btn--disabled {
		opacity: 0.3;
		cursor: not-allowed;
	}
</style>
